import{_ as r,C as s,c as n,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Forecast","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/reporting/forecast.md","filePath":"master/sales/crm/reporting/forecast.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/reporting/forecast.md"};function h(d,e,g,c,p,u){const o=s("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="forecast" tabindex="-1">Forecast <a class="header-anchor" href="#forecast" aria-label="Permalink to &quot;Forecast&quot;">​</a></h1><p>The forecast puts your opportunities on a board with one column per month. Each column shows how many deals you plan to close that month and the revenue you can realistically expect from them. You use it to plan ahead and to spot months with too few deals.</p><blockquote><p><strong>In simple words:</strong> The forecast is a month-by-month board of the money you expect to win. You can drag a deal to another month.</p></blockquote><p>Open <code>CRM → Reporting → Forecast</code>.</p><h2 id="the-forecast-board" tabindex="-1">The forecast board <a class="header-anchor" href="#the-forecast-board" aria-label="Permalink to &quot;The forecast board&quot;">​</a></h2>',5)),a(o,{src:"/images1/crm/forecast-board.png",alt:"Forecast board with a column for each month, showing the deal count and total revenue in each column header"}),e[1]||(e[1]=t('<p>The board opens in the <strong>Board</strong> view. The page also offers <strong>List</strong> and <strong>Graph</strong> (see below).</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong>None:</strong> Opportunities that have no <strong>Expected Closing</strong> date.</li><li><strong>Current month:</strong> Highlighted. It always shows.</li><li><strong>Next three months:</strong> Always shown, even when empty.</li><li><strong>Later months:</strong> A column appears for every month that has at least one deal.</li></ul><p>Months before the current month are not shown. Deals with an older closing date are left out of the board.</p><p><strong>Example:</strong> Today is 3 November 2026. The board shows <strong>None</strong>, <strong>November 2026</strong>, <strong>December 2026</strong>, <strong>January 2027</strong> and <strong>February 2027</strong>. February is empty and shows &quot;No opportunities to forecast&quot;.</p><h3 id="column-header" tabindex="-1">Column header <a class="header-anchor" href="#column-header" aria-label="Permalink to &quot;Column header&quot;">​</a></h3><p>Each header shows the month, the number of deals, and an amount. The amount is the <strong>prorated revenue</strong> of the column. That is expected revenue times probability for each deal, added together. It is not the full deal value.</p><p><strong>Example:</strong> <strong>November 2026</strong> shows 2 deals and <strong>$93,600.00</strong>. The two deals are worth $96,000 at 70% and $48,000 at 55%. That gives 67,200 plus 26,400, which is 93,600.</p><h3 id="cards" tabindex="-1">Cards <a class="header-anchor" href="#cards" aria-label="Permalink to &quot;Cards&quot;">​</a></h3>',9)),a(o,{src:"/images1/crm/forecast-card.png",alt:"Forecast card showing the opportunity name, expected and recurring revenue, customer and tags"}),e[2]||(e[2]=t('<p>Each card shows:</p><ul><li>The opportunity name.</li><li>The <strong>Expected Revenue</strong>, and below it the recurring revenue with its plan, for example <code>+ $18,000.00 Yearly</code>.</li><li>The customer.</li><li>The tags, in their colours.</li></ul><p>Click a card to open the opportunity.</p><h3 id="move-a-deal-to-another-month" tabindex="-1">Move a deal to another month <a class="header-anchor" href="#move-a-deal-to-another-month" aria-label="Permalink to &quot;Move a deal to another month&quot;">​</a></h3><ol><li>Drag a card from one column to another.</li><li>Drop it. A message says <strong>Expected closing date updated</strong>.</li></ol><p>The deal&#39;s <strong>Expected Closing</strong> becomes the last day of the new month. Dropping it in <strong>None</strong> clears the date. You need permission to edit the opportunity, or a red message tells you that you are not allowed to change it.</p><h2 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h2><p>Use the view switch to change how you see the same data.</p><table tabindex="0"><thead><tr><th>View</th><th>Use it to</th></tr></thead><tbody><tr><td><strong>Board</strong></td><td>Move deals between months.</td></tr><tr><td><strong>List</strong></td><td>Read rows and totals, and select rows for bulk actions.</td></tr><tr><td><strong>Graph</strong></td><td>See a bar chart. The default is <strong>Prorated Revenue by Expected Closing</strong>.</td></tr></tbody></table><h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><p>The tabs above the board are the same as in the pipeline: <strong>Default</strong>, <strong>My Pipeline</strong>, <strong>Open</strong>, <strong>Won</strong> and <strong>Lost</strong>. Open the tab menu for <strong>Unassigned</strong>.</p><ul><li><strong><em>My Pipeline:</em></strong> Opportunities where you are the salesperson.</li><li><strong><em>Open:</em></strong> Opportunities that are not in a won stage.</li><li><strong><em>Won:</em></strong> Opportunities in a won stage.</li><li><strong><em>Lost:</em></strong> Opportunities you marked as lost.</li></ul><h3 id="columns-in-the-list-view" tabindex="-1">Columns in the list view <a class="header-anchor" href="#columns-in-the-list-view" aria-label="Permalink to &quot;Columns in the list view&quot;">​</a></h3><p><strong>Name</strong>, <strong>Type</strong>, <strong>Customer</strong>, <strong>Stage</strong>, <strong>Expected Revenue</strong>, <strong>Probability</strong>, <strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Expected Closing</strong>, <strong>Created On</strong> and <strong>Closed On</strong>. The column toggle adds <strong>Lost Reason</strong>, <strong>Country</strong> and <strong>City</strong>. An extra column shows the measure you chose.</p><h3 id="search-filter-group-and-export" tabindex="-1">Search, filter, group and export <a class="header-anchor" href="#search-filter-group-and-export" aria-label="Permalink to &quot;Search, filter, group and export&quot;">​</a></h3><ul><li>Type in the search box to find an opportunity by name or customer.</li><li>Use the <strong>Salespeople</strong> and <strong>Sales Teams</strong> filters to look at one person or team.</li><li>Use the filter builder for rules on <strong>Salesperson</strong>, <strong>Active</strong>, <strong>Won</strong>, <strong>Closed Date</strong> and similar fields.</li><li>Use <strong>Group by</strong> in the list or graph. The choices are <strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Stage</strong>, <strong>City</strong>, <strong>Country</strong>, <strong>Lost Reason</strong>, <strong>Company</strong>, <strong>Campaign</strong>, <strong>Medium</strong>, <strong>Source</strong>, <strong>Expected Closing</strong>, <strong>Creation Date</strong>, <strong>Conversion Date</strong> and <strong>Closed Date</strong>.</li><li>Select rows in the list and use the bulk actions to export, delete, restore, mark as lost, merge, or send email or SMS.</li></ul><p>See <a href="./../../../getting-started/search-filter-group.html">Search, filter and group records</a>.</p><h2 id="read-the-forecast" tabindex="-1">Read the forecast <a class="header-anchor" href="#read-the-forecast" aria-label="Permalink to &quot;Read the forecast&quot;">​</a></h2><ol><li>Open <code>CRM → Reporting → Forecast</code>.</li><li>Look at the header of each month. Compare the deal count and the amount.</li><li>Open a card that looks too large or too small and check its <strong>Probability</strong>.</li><li>Drag deals whose date is wrong to the correct month.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Review the board every week. Move a deal as soon as the customer changes the date.</p></div><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>The board reads opportunities only. Leads do not appear until you convert them.</li><li>A deal sits in the month of its <strong>Expected Closing</strong> date. Without a date, it sits in <strong>None</strong>.</li><li>Dragging a card changes the opportunity itself. The pipeline, Pipeline analysis and Lead analysis show the new date too.</li><li>The amount uses the <strong>Probability</strong> saved on each opportunity. See <a href="./../assign-and-track/lead-scoring.html">Lead scoring</a> for how it is set.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../pipeline/manage-opportunities.html">Manage opportunities</a></li><li><a href="./pipeline-analysis.html">Pipeline analysis</a></li><li><a href="./">Reporting overview</a></li></ul>',24))])}const f=r(l,[["render",h]]);export{b as __pageData,f as default};
